Quelle est la sortie du fragment de code C++ suivant ?

int myInt1 = 3, myInt2 = 3;
int *pnt1 = &myInt1, *pnt2 = &myInt2;
myInt1 = ++(*pnt1) + (*pnt1);
myInt2++;
myInt2 = (*pnt2) + (*pnt2);
std::cout << myInt1 << myInt2;

Quelle est la valeur affichée à la sortie du fragment de code C++ suivant ?

void SetElements(int index, int **array, int value = 0) {
    (*array)[*(&index)] = value;
};
int main() {
    int *point1, *point2;
    point1 = new int[1];
    point2 = new int[2];
    *point1 = 0;
    SetElements(*&*point1, &point2);
    point1[0] = 1;
    SetElements(*&*point1, &point2, *point1);
    std::cout << (*point1) << point2[(*point1)-1];
    delete[] point1;
    delete[] point2;
}

Quel est le résultat de l'exécution du code C++ suivant ?

int i = 4;
if ((i == 3) && (i / (i - 4) == 0))
    std::cout << "OK";
std::cout << "AB";

Soit la classe D suivante :

class D {
    public int x;
    public D() { x = 3; }
    public D(int a) { this(); x = x + a; }
    public D(int a, int b) { this(b); x = x - a; }
}

Qu'affiche le code suivant ?

D a = new D(5, 6); System.out.println(a.x);
